children.text:
@font-face {
    font-family: 'Ahem';
    src: url('file:///Users/henryluo/Projects/lambda-test/layout/data/support/ahem3.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
}

/* establish context */
.container {
  clear: both;
  padding: 10px;
  color: blue;
  font: 20px/1 Ahem;
}
.zero {
  width: 0;
}
.infinite {
  width: 400px; /* close enough */
}

/* visualize size contribution */
.container > div {
  float: left; /* shrinkwrap */
  border: solid orange 20px;
  border-style: none solid;
}
.container > div > div {
  border-right: solid 20px aqua;
}

/* controls for width, max-width */
/* content = 100% = 80px = 4ch + border */
/* choose sizes that are larger than content to see if how they take effect */
.control {
  width: 60px;
}
.raw-percent,
.calc-percent {
  width: 40px;
  margin-right: 20px;
}
.no-percent {
  width: 40px;
}
